def file_from_modpath(modpath, path=None, context_file=None):
    """Given a mod path (i.e. split module / package name), return the
    corresponding file.

    Give priority to source files:
      * if modpath is a package, try to find an __init__.py file
      * otherwise, try to find a .py file
      * if not found, try to find a .pyc file

    :param modpath: The module's path
    :param path: The path to search
    :param context_file: The file that is importing the module
    :return: The path to the module file
    :rtype: str
    """
    if modpath[0] == "xml":
        # handle differences between python and xml packages
        return _file_from_modpath(modpath, context_file)
    path = path or sys.path
    if not isinstance(path, list):
        path = [path]
    for entry in path:
        if entry == "":
            entry = os.getcwd()
        try:
            return _file_from_modpath([entry] + modpath, context_file)
        except ImportError:
            continue
    raise ImportError(f"No module named {modpath[0]}")
