def get_module_files(
    src_directory: str, blacklist: Sequence[str], list_all: bool = False
) -> list[str]:
    """Given a package directory return a list of all available python
    module's files in the package and its subpackages.

    :param src_directory:  the directory path of the package
    :param blacklist: the list of files or directories to ignore.
    :param list_all: if all files (including those in packages without __init__.py)
        should be returned. Defaults to False.
    """
    files = []

    if list_all:
        if os.path.exists(os.path.join(src_directory, "__init__.py")):
            files.append(os.path.join(src_directory, "__init__.py"))

        for name in os.listdir(src_directory):
            path = os.path.join(src_directory, name)
            if path in blacklist:
                continue
            if os.path.isdir(path):
                files += get_module_files(path, blacklist, list_all)
            elif name.endswith(".py"):
                files.append(path)
    else:
        for name in os.listdir(src_directory):
            path = os.path.join(src_directory, name)
            if path in blacklist:
